window.RP_SESSION={"id":"S-53299175aae4","messages":[{"id":"RP-III-0115289","time":"2026-06-26T23:54:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 드디어 지독하던 밤이 져물고 아침이 찾아왔습니다. 오늘은 라운데라님의 영광 아래 날이 좋군요. 분명 그 분께서도 좋은 날인걸 아신거겠죠. 오늘 하루도 살아갈 수 있음을 감사하며 라운데라께 기도를 올립니다. 그 후 세면을 통해 이 한 옴 정갈히 하면 오늘의 일과가 시작됩니다. 우선 닭들이 잘 있는지 살펴봅시다. 몸이 좀 뜨끈하네요!\n\n \"안녕하십니까 피터 사제님! 오랜만임다!\"\n\n 오늘 모이 담당인 신학생들이 미리 나와있었네요. 못 본새 많이 컸습니다. 그래도 그 동근 뺨에 솜털이 남아있어 아직 귀엽기만합니다.\n\n \"좋은 아침이에요~.\"\n\n 그 다음엔 역시 식사준비지요. 오늘은 특별한 날이라 원장님이 닭을 한 마리 잡으신답니다. 무려 제가 전쟁에서 생환했으니까요!\n 제 축하상을 직접 차린다는 건 조금 이상한 일인거 같긴 해도, 역시 이런 걸 아이들을 시킬 순 없는 거겠죠. 저는 닭장 안에 손을 넣어, 실한 놈의 모가지를 잡아 비틀었습니다.\n 어부의 외아들로서, 음식 손질을 위한 피야","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115290","time":"2026-06-26T23:56:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" ...","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115291","time":"2026-06-26T23:56:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115292","time":"2026-06-26T23:56:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"괜히 있어보이기 위한 ...","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115293","time":"2026-06-26T23:59:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 눈을 감으면, 내가 돕지 못한 사람들이 떠올랐다.\n\n메시지가 삭제되었습니다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115294","time":"2026-06-27T00:11:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"으어어어엉.\"","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115295","time":"2026-06-27T00:12:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 사이먼 피터 포레스트. 22세. 교회로 돌아온지 이틀만에 몸살로 알아눕다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115296","time":"2026-06-27T00:18:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" '억울해!'\n\n 기껏 고향 땅에 살아돌아왔는데, 침대에 누워 있어야만 한다니! 강호의 도리가 땅에 떨어졌구나! 아아 라운데라시여!\n \n ...훌쩍.\n\n \"흐엉.\"\n\n 이래서야 제대로 인사할 수는 없겠다. 헉. 내가 오늘 아침해서 다른 동료들에게 옮는거 아니겠지?\n ...\n\n \"흐엉엉.\"\n\n 이게 다 크아킨 때문이다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115297","time":"2026-06-27T00:26:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 베개 밑 종이가 바시락거렸다. 그러고보니 어젯 밤 돌아오자 마자 베개 밑에 쑤셔놨었던게 있다. 나는 밤새 내 머리에 눌려있던 종이 봉투를 빼내었다. 내가 따로 잠버릇이 있지는 않은지라, 몇 번 손바닥으로 눌러주니 제법 괜찮은 상태가 되었다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115298","time":"2026-06-27T00:27:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 크아킨을 무찌른 자가 몸 담은, 어설픈 용맹에 대한 추천장.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115299","time":"2026-06-27T00:27:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 내 것이다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115300","time":"2026-06-27T00:29:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그리고 갈 것이다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115301","time":"2026-06-27T00:31:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"인정 받아서 기쁜 것도 분명 컸다. 나 관심 받는거 좋아해. 그보다는","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115302","time":"2026-06-27T00:32:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"일단 낭만이 있고...","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115303","time":"2026-06-27T00:33:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 현재 명성이 명성이니 만큼 크게 이상한 곳은 아닐테고, 동경하는 것도 있다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115304","time":"2026-06-27T00:41:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 무엇보다, 내가 좀 더 폭 넓게 누군가를 도울 수 있는 기회였다. 이곳이 자선단체가 아니라는 것 쯤은 알고 있다. 그러나 의뢰란 그것이 선의와 정의에 기반하지 않더라도 그 자체가 도움을 주고 받는데에 목적이 있다. 그것만으로 족한 일이었다. 나는 초대장을 제대로 서랍 안에 넣으려 했다.\n\n \"자네, 안 쉬고 뭐하는가?\"\n\n 꺄악","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115305","time":"2026-06-27T14:43:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115306","time":"2026-06-27T14:43:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"퀴긴아 또 일 안하니","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0115307","time":"2026-06-27T14:46:00+09:00","room":"RP III","name":"Maria Anaïs Ésther","profile":"Maria Anaïs Ésther","identity":"unresolved","type":"dialogue","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
